SELECT ?manager WHERE {
  # Find the 2019 Tour of Turkey event
  ?event wdt:P31 wd:Q45804 ;
         rdfs:label 'Tour of Turkey'@en ;
         wdt:P585 ?date.
  FILTER (YEAR(?date) = 2019).

  # Get the second-place rider with time difference > 1 minute
  ?result wdt:P1340 ?event ;
          wdt:P1554 2 ;
          wdt:P158 ?rider ;
          wdt:P169 ?rider.
  ?rider wdt:P154 ?team.
  ?team wdt:P4340 ?manager.
}

SELECT ?manager WHERE {
  # Find the 2019 Tour of Turkey event
  ?event wdt:P31 wd:Q17013006 ;
         wdt:P131 wd:Q607 ;
         rdfs:label "Tour of Turkey"@en ;
         wdt:P585 ?eventDate.
  FILTER (YEAR(?eventDate) = 2019).

  # Get the second-place result with time difference > 1 minute (60 seconds)
  ?result wdt:P1340 ?event ;
          wdt:P1554 2 ;
          wdt:P1368 ?time_diff.
  FILTER (xsd:float(?time_diff) > 60).

  # Get the team from the race result
  ?result wdt:P127 ?team.

  # Get the team manager
  ?team wdt:P4340 ?manager.
}

